function soupServings(n) {
  if (n > 4800) {
    return 1;
  }
  const units = Math.ceil(n / 25);
  const memo = Array.from({ length: units + 1 }, () => new Array(units + 1).fill(-1));

  const serve = (a, b) => {
    if (a <= 0 && b <= 0) {
      return 0.5;
    }
    if (a <= 0) {
      return 1;
    }
    if (b <= 0) {
      return 0;
    }
    if (memo[a][b] >= 0) {
      return memo[a][b];
    }
    const total = serve(a - 4, b) + serve(a - 3, b - 1) + serve(a - 2, b - 2) + serve(a - 1, b - 3);
    memo[a][b] = total / 4;
    return memo[a][b];
  };

  return serve(units, units);
}

