function soupServings(n) {
  // Push probability mass forward turn by turn in real millilitres; past 10000 mL the answer is 1 to within 1e-10.
  if (n > 10000) return 1;
  if (n === 0) return 0.5;
  const pours = [[100, 0], [75, 25], [50, 50], [25, 75]];
  let answer = 0;
  let layer = new Map([[n + ',' + n, 1]]);
  while (layer.size > 0) {
    const next = new Map();
    for (const [key, chance] of layer) {
      const [soupA, soupB] = key.split(',').map(Number);
      for (const [pourA, pourB] of pours) {
        const restA = soupA - pourA, restB = soupB - pourB, share = chance / 4;
        if (restA <= 0 && restB <= 0) answer += share / 2;
        else if (restA <= 0) answer += share;
        else if (restB > 0) next.set(restA + ',' + restB, (next.get(restA + ',' + restB) || 0) + share);
      }
    }
    layer = next;
  }
  return answer;
}

